{
    var count = 0;
    while (count < numberToCancel && queue.Count > 0)
    {
        var item = queue.First(p => p.Item == itemName);
        if (item != null)
        {
            playerResources.GiveCash(item.TotalCost - item.RemainingCost); // refund what's been paid so far
